<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>SoundCloud Player Demo</title>
  <style>
    .sc-player { width: 100%; max-width: 600px; height: 166px; }
    #custom-controls { margin-top: 10px; }
    #progress { height: 5px; background: #ff5500; width: 0%; }
  </style>
</head>
<body>

<h2>Embedded SoundCloud Track (iframe)</h2>
<iframe class="sc-player"
        src="https://w.soundcloud.com/player/?url=https%3A//api.soundcloud.com/tracks/123456789&color=%23ff5500&auto_play=false">
</iframe>

<hr>

<h2>Custom Player (SDK)</h2>
<div id="player-container"></div>

<div id="custom-controls">
  <button id="playBtn">Play</button>
  <button id="pauseBtn">Pause</button>
  <div style="background:#ddd; width:100%; height:5px; margin-top:5px;">
    <div id="progress"></div>
  </div>
</div>

<script src="https://connect.soundcloud.com/sdk/sdk-3.3.2.js"></script>
<script>
  // 1️⃣ Initialize SDK
  SC.initialize({
    client_id: 'YOUR_CLIENT_ID'   // <-- replace
  });

