### 2.2. Handle the **callback** on your server

Below are minimal implementations for three common back‑ends. Choose the one that matches your stack, replace the placeholders with your actual values, and you’ll be able to exchange the `code` for an access token.

---

#### **Node.js (Express) – full example**

```js
// ---------------------------------------------------
// 1️⃣  Install dependencies first:
//    npm i express express-session axios qs
// ---------------------------------------------------
const express   = require('express');
const session   = require('express-session');
const axios     = require('axios');
const qs        = require('querystring');

const app = express();
app.use(session({
  secret: 'a‑very‑random‑session‑secret',
  resave: false,
  saveUninitialized: true,
}));

// ------------------------------------------------------------------
// 2️⃣  Helper to generate a random state string (you can use any lib)
// ------------------------------------------------------------------
function generateState() {
  return require('crypto').randomBytes(16).toString('hex');
}

// ------------------------------------------------------------------
// 3️⃣  Route that starts the OAuth flow (e.g., /login/soundcloud)
// ------------------------------------------------------------------
app.get('/login/soundcloud', (req, res) => {
  const state = generateState();
  req.session.scState = state;               // store for later verification

  const redirectUri = encodeURIComponent('https://mywebsite.com/auth/soundcloud/callback');
  const authUrl = `https://soundcloud.com/connect?client_id=client321` +
                  `&redirect_uri=${redirectUri}` +
                  `&response_type=code` +
                  `&scope=non-expiring` +
                  `&state=${state}`;

  res.redirect(authUrl);
});

