  const { code, state, error } = req.query;

  // ---- error handling -------------------------------------------------
  if (error) {
    return res.status(400).send(`SoundCloud error: ${error}`);
  }

  // ---- verify state ----------------------------------------------------
  if (!state || state !== req.session.scState) {
    return res.status(400).send('Invalid state parameter');
  }

  // ---- exchange code for access token ----------------------------------
  try {
    const tokenResp = await axios.post(
      'https://api.soundcloud.com/oauth2/token',
      qs.stringify({
        client_id:     'client321',
        client_secret: '123456',               // <-- your client secret
        grant_type:    'authorization_code',
        redirect_uri:  'https://mywebsite.com/auth/soundcloud/callback',
        code:          code,
      }),
      { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
    );

    const { access_token, expires_in } = tokenResp.data;

    // ---- store token (example: in session) -----------------------------
    req.session.scAccessToken = access_token;
    req.session.scExpiresAt   = Date.now() + expires_in * 1000;

    // ---- now you can call SoundCloud APIs on behalf of the user -------
    // e.g., GET https://api.soundcloud.com/me?oauth_token=access_token

    res.redirect('/dashboard');   // or wherever you want the user to go
  } catch (e) {
    console.error('Token exchange failed:', e.response?.data || e);
    res.status(500).send('Failed to obtain access token');
  }
});

// ------------------------------------------------------------------
// 5️⃣  Start the server
// ------------------------------------------------------------------
app.listen(3000, () => console.log('App listening on http://localhost:3000'));
```

---

#### **Python (Flask) – full example**

```python
# ---------------------------------------------------
# 1️⃣  Install dependencies:
#    pip install Flask requests
# ---------------------------------------------------
from flask import Flask, request, redirect, session, url_for
import os, secrets, requests

app = Flask(__name__)
app.secret_key = os.urandom(24)   # keep this secret in production!

CLIENT_ID     = 'client321'
CLIENT_SECRET = '123456'          # <-- your client secret
REDIRECT_URI  = 'https://mywebsite.com/auth/soundcloud/callback'

# ------------------------------------------------------------------
# 2️⃣  Start OAuth – /login/soundcloud
# ------------------------------------------------------------------
@app.route('/login/soundcloud')
def login_soundcloud():
    state = secrets.token_hex(16)
    session['sc_state'] = state

    auth_url = (
        'https://soundcloud.com/connect?'
        f'client_id={CLIENT_ID}'
        f'&redirect_uri={REDIRECT_URI}'
        '&response_type=code'
        '&scope=non-expiring'
        f'&state={state}'
    )
    return redirect(auth_url)

# ------------------------------------------------------------------
# 3️⃣  Callback – /auth/soundcloud/callback
# ------------------------------------------------------------------
@app.route('/auth/soundcloud/callback')
def soundcloud_callback():
    error = request.args.get('error')
    if error:
        return f'SoundCloud error: {error}', 400

    code  = request.args.get('code')
    state = request.args.get('state')

    # ---- verify state -------------------------------------------------
    if not state or state != session.get('sc_state'):
        return 'Invalid state parameter', 400

    # ---- exchange code for token ---------------------------------------
    token_resp = requests.post(
        'https://api.soundcloud.com/oauth2/token',
        data={
            'client_id':     CLIENT_ID,
            'client_secret': CLIENT_SECRET,
            'grant_type':    'authorization_code',
            'redirect_uri':  REDIRECT_URI,
            'code':          code,
        }
    )
    token_resp.raise_for_status()
    token_data = token_resp.json()
    access_token = token_data['access_token']

    # ---- store token (example: in session) -----------------------------
    session['sc_access_token'] = access_token
    session['sc_expires_at']   = token_data.get('expires_in', 0) + int(time.time())

    return redirect(url_for('dashboard'))

# ------------------------------------------------------------------
# 4️⃣  Dummy dashboard route
# ------------------------------------------------------------------
@app.route('/dashboard')
def dashboard():
    token = session.get('sc_access_token')
    if not token:
        return redirect(url_for('login_soundcloud'))

    # Example API call – get the logged‑in user profile
    profile = requests.get(
        'https://api.soundcloud.com/me',
        params={'oauth_token': token}
    ).json()
    return f'Hello, {profile.get("username")}!'

if __name__ == '__main__':
    app.run(port=5000, debug=True)
```

