             . "&redirect_uri={$redirectUri}"
             . "&response_type=code"
             . "&scope=non-expiring"
             . "&state={$state}";

    return redirect($authUrl);
});

// ------------------------------------------------------------------
// 2️⃣  Callback – /auth/soundcloud/callback
// ------------------------------------------------------------------
Route::get('/auth/soundcloud/callback', function (Illuminate\Http\Request $request) {
    $error = $request->query('error');
    if ($error) {
        abort(400, "SoundCloud error: $error");
    }

    $code  = $request->query('code');
    $state = $request->query('state');

    // ---- verify state ------------------------------------------------
    if ($state !== session('sc_state')) {
        abort(400, 'Invalid state parameter');
    }

    // ---- exchange code for token ------------------------------------
    $response = Http::asForm()->post('https://api.soundcloud.com/oauth2/token', [
        'client_id'     => 'client321',
        'client_secret' => env('SOUNDCLOUD_CLIENT_SECRET', '123456'), // <-- secret
        'grant_type'    => 'authorization_code',
        'redirect_uri'  => 'https://mywebsite.com/auth/soundcloud/callback',
        'code'          => $code,
    ]);

    if ($response->failed()) {
        abort(500, 'Token exchange failed');
    }

    $data = $response->json();
    $accessToken = $data['access_token'];

    // ---- store token (example: in session) -------------------------
    session(['sc_access_token' => $accessToken]);

    return redirect('/dashboard');
});

