<!-- Hidden SVG template -->
<svg id="typing-template" width="0" height="0" style="position:absolute;visibility:hidden;">
  <symbol id="typing-symbol" viewBox="0 0 300 30">
    <text x="0" y="20" font-family="monospace" font-size="20" fill="#333"
          id="typing-text"></text>
    <rect x="0" y="4" width="2" height="22" fill="#333"
          id="typing-cursor"></rect>
  </symbol>
</svg>

<script>
/* ---------- 1️⃣  Utility to clone the SVG ---------- */
function createTypingSVG(svgId) {
  const tmpl = document.querySelector('#typing-template #typing-symbol');
  const clone = tmpl.cloneNode(true);
  clone.setAttribute('id', svgId);
  clone.setAttribute('width', '100%');
  clone.setAttribute('height', '30');

  clone.querySelector('#typing-text')
       .setAttribute('id', `${svgId}-text`);
  clone.querySelector('#typing-cursor')
       .setAttribute('id', `${svgId}-cursor`);

  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.appendChild(clone);
  return svg;
}

/* ---------- 2️⃣  TypingAnimator class ---------- */
class TypingAnimator {
  constructor(field, svg, opts = {}) {
    this.field = field;
    this.svg = svg;
    this.svgId = svg.id;
    this.textNode = svg.querySelector(`#${this.svgId}-text`);
    this.cursorNode = svg.querySelector(`#${this.svgId}-cursor`);

    this.settings = {
      typingSpeed: 300,
      delayBeforeStart: 200,
      cursorBlinkRate: 500,
      ...opts
    };
    this._applySettings();

    this._onFocus = this._onFocus.bind(this);
    this._onInput = this._onInput.bind(this);
    this._onBlur  = this._onBlur.bind(this);

    field.addEventListener('focus', this._onFocus);
    field.addEventListener('input', this._onInput);
    field.addEventListener('blur',  this._onBlur);
  }

  _applySettings() {
    setTypingAnimation({
      typingSpeed: this.settings.typingSpeed,
      delayBeforeStart: this.settings.delayBeforeStart
    });
    setCursorBlinkRate({
      blinkRate: String(this.settings.cursorBlinkRate),
      svgId: this.svgId
    });
  }

  _onFocus() {
    this.field.classList.add('typing-active');
    const start = this.field.value || this.field.placeholder || '';
    this._setSVGText(start);
    this._showCursor();
  }

  _onInput(e) {
    this._setSVGText(e.target.value);
  }

  _onBlur() {
    this.field.classList.remove('typing-active');
    pauseTypingAnimation({ pauseDuration: '500', svgId: this.svgId });
    setTimeout(() => this._hideCursor(), 500);
  }

  _setSVGText(str) {
    const esc = str.replace(/&/g,'&amp;')
                   .replace(/</g,'&lt;')
                   .replace(/>/g,'&gt;');
    this.textNode.textContent = esc;
    const bbox = this.textNode.getBBox();
    this.cursorNode.setAttribute('x', bbox.x + bbox.width + 1);
  }

  _showCursor() { this.cursorNode.style.display = 'block'; }
  _hideCursor() { this.cursorNode.style.display = 'none'; }

  /* Public helpers */
  setSpeed(wpm){ this.settings.typingSpeed = wpm; this._applySettings(); }
  setDelay(ms){ this.settings.delayBeforeStart = ms; this._applySettings(); }
  setCursorBlink(ms){ this.settings.cursorBlinkRate = ms; this._applySettings(); }
}

/* ---------- 3️⃣  Initialise on DOM ready ---------- */
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.typing-wrapper').forEach(wrapper => {
    const fieldId = wrapper.dataset.for;
    const field   = document.getElementById(fieldId);
    if (!field) return;

    const svgId = field.dataset.typingId || `typing-${fieldId}`;
    const svg   = createTypingSVG(svgId);
    wrapper.appendChild(svg);

    new TypingAnimator(field, svg, {
      typingSpeed: 250,
      delayBeforeStart: 150,
      cursorBlinkRate: 600
    });
  });
});
</script>
</body>
</html>
```

Open the file in a browser, click inside **Name** or **Message**, and watch the SVG “type” the placeholder text. As you type, the SVG mirrors your input in real time, complete with a blinking cursor.

